from pathlib import Path
from PIL import Image

root = Path(__file__).resolve().parents[1] / 'public' / 'images'
for name in ['recurso1', 'recurso2', 'recurso3']:
    image = Image.open(root / (name + '.png'))
    image.save(root / (name + '.webp'), quality=86, method=6)
image = Image.open(root / 'isologoblack.png')
image = image.crop(image.getchannel('A').getbbox())
image.thumbnail((56,56),Image.Resampling.LANCZOS)
favicon = Image.new('RGBA',(64,64),'#8cff2e')
favicon.alpha_composite(image,((64-image.width)//2,(64-image.height)//2))
favicon.save(root / 'favicon.png')

def svg(name, background, content):
    (root / name).write_text(f'<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="900" viewBox="0 0 1200 900"><rect width="1200" height="900" fill="{background}"/>{content}</svg>',encoding='utf-8')

